INSERT INTO data_conflicts (product_id,attribute,values,status) SELECT p.id,'centrifugalForce_DPU45YEH_vs_DPU4045Yeh','{"candidates":[{"value":"40 кН","sources":["https://e-katalog.kz/WACKER-NEUSON-DPU-4045-YE.htm","https://ryvok.ru/tehnika/vibropliti/wacker-neuson-dpu-4045-yeh","https://wacker-center.ru/catalog/vibroplita-dizelnaya-dpu-4045Ye-wacker-neuson/"]},{"value":"45 кН","sources":["https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_benzinovaya_wacker_neuson_bpu_6275_ah_452_kg (блок похожих товаров: DPU 45 YEH 45 кН, 376 кг)","https://energo-mechanika.ru/product/vibroplita-benzinovaya-wacker-neuson-bpu-3750-ats-professionalnaya-240-kg-37-kn-honda-gx270 (блок аналогов: DPU 45 YEH 45 кН Yanmar L70)"]}],"resolution":"Оба SKU имеют одинаковый вес 376 кг, один двигатель Yanmar L70 и одну платформу 900x440 — это одна машина; ''DPU 45 YEH'' является маркетинговым именем DPU4045Yeh. По правилу номенклатуры WN (4045 = 40 кН, 450 мм) корректное значение силы — 40 кН, но в карточке SKU ''DPU 45 YEH'' значение 45 кН уже опубликовано поставщиком. Требуется запрос поставщику/замер паспорта."}'::jsonb,'open' FROM products p WHERE p.source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_dizelnaya_wacker_neuson_dpu_4045yeh_376_kg/' ON CONFLICT (product_id,attribute,status) DO UPDATE SET values=EXCLUDED.values;
