UPDATE products SET specs=specs||'{"тип":"реверсивная гидростатическая, электрическая (нулевые выбросы)","вес":"750 кг (803 кг с опц. удлинителями и ACE)","центробежнаяСила":"70 кН","частота":"54 Гц (3240 об/мин)","ширинаРабочая":"650 / 800 / 950 мм","длинаПлиты":"1070 мм","амплитуда":"4,0 мм","поверхностноеДавление":"14,2 Н/см²","привод":"электромотор Inmotion GSM306, 3-фазный PMSM, 10,2 кВт (13,7 л.с.) пост. @2400 об/мин","аккумулятор":"LiFePO4, 51,2 В DC, 180 Ач, 9,216 кВт·ч","зарядное":"Zivan SG3; вход 95–265 В AC 50/60 Гц; выход 58,4 В DC / 60 А","зарядка":"0–80% ≈180 мин; 0–100% ≈240 мин (сеть 230 В)","автономность":"до ~70 мин на полном заряде","Применение":"Уплотнение связных и несвязных грунтов там, где запрещены выхлоп и шум: подвалы, тоннели, закрытые и городские площадки.","Особенности":"нулевые выбросы — работа в помещениях и на режимных объектах; трёхвальный exciter Ammann — плавный ход и подъёмная способность; orbitrol-управление ходом; виброизолированная ручка с регулировкой и фиксацией; капот для защиты узлов и доступа при обслуживании; аварийная остановка, счётчик моточасов; центральная точка строповки; опции: удлинительные плиты 75/150 мм, система контроля уплотнения ACE; расширенная гарантия 3 года","Разновидности":"eAPH 70/95 r9 (страница en-US ammann.com)","Запчасти и расходники":"Maintenance kit (комплект ТО Ammann) (официальная опция из списка Options ammann.com); Удлинительные плиты 75 мм и 150 мм (официальная опция, вес с ними 803 кг)","Инструкции PDF":"https://www.swecon.se/contentassets/2bfa34aa344c41558f996adf5b65a4ad/eaph_7095-vibratory_plate-data_sheet-mss-3145-01-en-1.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_elektricheskaya_ammann_eaph_70_95_750_kg/';
UPDATE products SET specs=specs||'{"тип":"реверсивная гидростатическая, дизель","центробежнаяСила":"85 кН","частота":"52 Гц (3120 вибр/мин)","ширинаРабочая":"650 / 800 / 950 мм","амплитуда":"4,1 мм","производительность":"1767 м²/ч (базовая плита)","поверхностноеДавление":"25,1 Н/см²","двигатель":"Kubota D902, дизель","мощность":"13,4 кВт @2600 об/мин (даташиты 2021–2023) или 16,1 кВт @3200 об/мин (текущий сайт ammann.com) — конфликт поколений данных","расходТоплива":"3,3 л/ч","топливо":"дизель; совместимо с HVO","Применение":"Тяжёлый класс: глубокие слои грунта, связные почвы, траншеи, крупные основания, работа на уклонах.","Особенности":"трёхвальный exciter — стабильный ход по тяжёлым связным грунтам и крутым уклонам; гидростатический привод; orbitrol-управление; работа на HVO (биодизель, −90% CO₂); центральная точка подъёма; CE; опции: ширины 800/950 мм, ACE, maintenance kit","Разновидности":"исполнения с шириной плиты 650 / 800 / 950 мм","Запчасти и расходники":"Maintenance kit Ammann для APH (официальная опция ammann.com); Расходные части Kubota D902 (фильтры масло/топливо/воздух, свечи накала) (подбираются по двигателю Kubota D902; артикулы не подтверждены)","Инструкции PDF":"https://www.kuhn.hr/Products/Ammann/Vibratory%20plates/APH-85-95/aph_8595_vibratory_plate_sell_sheet_mss-1063-07-en_210923.pdf; https://wegenbouwmachine.nl/wp-content/uploads/2022/02/APH-85-95-technische-specificaties-EN.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_dizelnaya_ammann_aph_85_95_760_kg/';
UPDATE products SET specs=specs||'{"тип":"реверсивная гидростатическая, дизель","вес":"471 кг базовая / до 525 кг с удлинителями","центробежнаяСила":"65 кН","частота":"55 Гц (3300 вибр/мин)","ширинаРабочая":"550 / 700 / 850 мм","габариты":"длина машины 930 мм (1840 с ручкой), высота 905 мм; длина плиты 470 мм; ручка 1000/1500 мм","двигатель":"Hatz 1D81S, дизель","мощность":"10,1 кВт (13,5 л.с.) ISO @3000 об/мин","расходТоплива":"2,5 л/ч","Применение":"Мощные задачи среднего тяжёлого класса: уплотнение грунта, траншеи, подготовка оснований, уклоны.","Особенности":"трёхвальный exciter Ammann; гидростатический привод + orbitrol; опциональная система измерения уплотнения ACE; центральная точка строповки; CE","Разновидности":"исполнения с шириной 550 / 700 / 850 мм","Запчасти и расходники":"Maintenance kit Ammann для APH (официальная опция ammann.com); Фильтры и свечи накала Hatz 1D81S (подбираются по двигателю; артикулы не подтверждены)","Инструкции PDF":"https://www.kuhn.si/Products/Ammann/Vibratory%20plates/APH-65-85/aph_6585_vibratory_plate_sell_sheet_mss-1062-07-en_230919.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_dizelnaya_ammann_aph_65_85_471_kg/';
UPDATE products SET specs=specs||'{"тип":"реверсивная гидростатическая, дизель","вес":"464 кг базовая / до 518 кг с удлинителями","центробежнаяСила":"60 кН","частота":"69 Гц (4140 вибр/мин)","ширинаРабочая":"550 / 700 / 850 мм","амплитуда":"1,9 мм","скорость":"до 28 м/мин","производительность":"1428 м²/ч","поверхностноеДавление":"23,2 Н/см²","уклон":"36% продольно, до 30° во все стороны","двигатель":"Hatz Supra 1D81S, дизель","мощность":"10,1 кВт (13,5 л.с.) @3000 об/мин","расходТоплива":"2,5 л/ч","бак":"7 л","Применение":"Уплотнение грунта и асфальта, траншеи и котлованы, обратная засыпка вдоль стен и фундаментов.","Особенности":"двухвальный exciter (double-shaft) — выше частота при меньшей силе, чем у APH 65/85; гидростатический привод + orbitrol; высокая надёжность и ресурс за счёт простой прочной конструкции; центральная строповка; электростартер","Разновидности":"исполнения с шириной 550 / 700 / 850 мм","Запчасти и расходники":"Фильтры Hatz Supra 1D81S (масло/топливо/воздух) (подбираются по двигателю; артикулы не подтверждены)","Инструкции PDF":"https://www.kuhn.hr/Products/Ammann/Vibratory%20plates/APH-60-85/aph_6085_vibratory_plate_sell_sheet_mss-1060-04-en_200305.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_dizelnaya_ammann_aph_60_85_464_kg/';
