UPDATE products SET specs=specs||'{"тип":"реверсивная гидравлическая, бензин","вес":"135 кг","центробежнаяСила":"25 кН","частота":"5400 вибр/мин","плита":"400×650 мм","габариты":"1350×400×880 мм","двигатель":"Honda GX160, 3,6 кВт (4,9 л.с.)","реверс":"бесступенчатый гидростатический","Применение":"Узкие траншеи и малые площади; песок, гравий, связные грунты; комфортное гидроуправление.","Особенности":"бесступенчатый гидростатический ход вперёд/назад; защита реверса: при отпускании рычага машина возвращается к медленному ходу вперёд; виброизолированные ручки, складывание на 45° и 90°; литой алюминиевый рычаг дросселя; ударостойкая открытая самоочищающаяся плита; герметичный кожух ремня и муфты; уплотнение «на месте» проблемных зон; электростартер (опция для дизелей серии)","Разновидности":"MH125-1 дизель KAMA KM173F/Kipor (155 кг), MH125-3 Robin EX17 (135 кг), MH125-5 дизель Lombardini LD225 (151 кг)","Запчасти и расходники":"Ремень привода для MSH125-3/-4 (powertool.ru); Свеча/фильтр Honda GX160","Инструкции PDF":"http://masaltamachine.es/1-3-4-hydraulic-plate-compactor-es/111571/"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_benzinovaya_masalta_mh125_4_gidravlicheskaya_114_kg/';
