UPDATE products SET specs=specs||'{"втулка_подшипника_распредвала_арт":"Wacker Neuson 5000095012","счетчик_моточасов_арт":"Wacker Neuson 5100011309","комплект_фильтров_арт":"КА-00042730 (набор БАКАУТ)","состав_комплекта":"масляный фильтр 5000094930/01480001 + топливный 5000022832/40089401 + воздушный 5000095091/01493001","аналог_воздушного_фильтра_hatz":"01493000/01493001 (заменяет WN 0095091)","масляный_фильтр_аналог_hatz":"000001480001 (HATZ 1D41/1D81)","двигатели_серии":"DPU 6555 Heh — Hatz 1D81S-358A (667 см³); DPU 5545 Hehap — Hatz 1D42S (445 см³); DPU 4545 HE — Hatz 1D42S (HIFI Filter); часть версий 1D41","совместимость":"Wacker Neuson DPU 4545 / DPU 5545 / DPU 6555 всех модификаций (He/Heh/Hes/Yeh/Heap и т.д.)","штатный_счетчик_моточасов":"встроен в версии Hech/Hecsh/Heh («Счетчик моточасов: да»)","Применение":"Регламентное ТО и ремонт дизельных реверсивных плит Wacker Neuson среднего/тяжелого класса: замена фильтров каждые 250 моточасов, восстановление ГРМ (втулка распредвала), контроль наработки (счетчик).","Особенности":"Оригинальные номера Wacker Neuson подтверждены внешними продавцами запчастей; Внимание: набор маркирован «двигатель HATZ 1D81», но часть DPU 4545/5545 комплектовалась Hatz 1D41/1D42S — перед покупкой сверять тип двигателя по шильдику; Аккумулятор гелевый 5100021329 и ручка газа в сборе — сопутствующие позиции той же группы","Разновидности":"Отдельные фильтры продаются по одному (масляный/топливный/воздушный); Аналоги Hatz 01493000 (воздушный), 01412900-класс (топливный), X282/000001480001 (масляный)","Запчасти и расходники":"Корпус масляного фильтра Hatz 1D41/1D81 (30 990 ₽, сопутствующий ремкомплект); Аккумулятор гелевый 5100021329 (для электростартера DPU 4545/5545/6555); Подшипник эксцентрика 5000103469 (см. отдельную запись)","Инструкции PDF":"https://bakautprof.ru/upload/documentation/Руководство%20по%20эксплуатации%20DPU%204545,%205545,%206555.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/raskhodniki/vtulka_podshipnika_raspredvala_dlya_vibroplit_dpu_4545_5545_6555/';
