UPDATE products SET specs=specs||'{"артикул_wacker_neuson":"5000103469","тип":"подшипниковый узел эксцентрикового вала вибровозбудителя","совместимость":"Wacker Neuson DPU 4545, DPU 5545, DPU 6555, DPU 130","цена_ориентир":"12 380 ₽ (bakautprof)","Применение":"Замена изношенного подшипника вибровозбудителя: устраняет повышенный шум, перегрев узла, потерю эффективности уплотнения.","Особенности":"Оригинальная деталь узла вибрации; Работает в условиях повышенной нагрузки, пыли и вибрации; Ключевой элемент, определяющий эффективность передачи центробежной силы на основание","Разновидности":"Смежные детали узла: шток вала эксцентрика WACKER (15 080 ₽), шестерня эксцентрика WACKER (3 960 ₽), сальник эксцентрика VP","Запчасти и расходники":"Шток вала эксцентрика WACKER (меняется вместе с подшипником при износе); Шестерня эксцентрика WACKER (сопутствующая деталь привода виброузла)","Инструкции PDF":"https://bakautprof.ru/upload/documentation/Руководство%20по%20эксплуатации%20DPU%204545,%205545,%206555.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/raskhodniki/podshipnik_ekstsentrika_dlya_vibroplit_dpu_4545_5545_6555_130/';
