UPDATE products SET specs=specs||'{"тип":"сверхтяжёлая реверсивная виброплита с дистанционным инфракрасным управлением, дизель","артикул":"5000610143","вес":"1185 кг (каталог bakautprof и большинство дилеров) / 1170 кг (даташит nt-rt, wackerneuson.com.ru); транспортный вес 1210 кг","центробежная сила":"130 кН","двигатель":"Kohler LDW 1404, 4 цилиндра, жидкостное охлаждение","мощность":"24.5 кВт","плита ШxД":"1200 x 1186 мм, сплит-конструкция (раздвоенная плита), толщина 14 мм","высота":"988 мм","частота":"58 Гц","скорость":"до 31 м/мин (рекордная для класса)","производительность":"до 2232 м²/ч (эквивалент ~7-тонного катка)","расход топлива":"4 л/ч","топливный бак":"18 л","привод":"гидростатический двухконтурный с электронным управлением","управление":"ИК-пульт ДУ с датчиком присутствия оператора: автостоп при приближении человека ближе ~2 м","Применение":"Промышленные объёмы: магистральные трубопроводы, насыпи, большие котлованы, аэродромы; замена лёгких катков там, где каток неприменим.","Особенности":"Одна из самых мощных серийных виброплит мира: 130 кН при управлении одним оператором с пульта; Концепция раздвоенной базовой плиты Wacker Neuson — маневренность и проход препятствий; Автоматические отключения при выходе оператора/машины за рабочую зону сигнала; Выдвижной приёмник ИК-управления защищён от повреждений; Оператор вне зоны вибрации, шума и пыли","Разновидности":"Логика суффиксов тяжёлой серии: L — тяжёлый класс с жидкостным охлаждением, e — электростартер, m — ручное управление, c — радиопульт ДУ; SKU bakautprof соответствует версии с пультом","Запчасти и расходники":"Расходники для Kohler LDW 1404 (фильтры, масло) и гидравлика — через дилерскую сеть WN (Отдельные артикулы в открытых источниках не зафиксированы)","Инструкции PDF":"https://wackerneuson.nt-rt.ru/images/manuals/DPU%20130.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_dizelnaya_wacker_neuson_dpu_130_le_na_pulte_1185_kg/';
UPDATE products SET specs=specs||'{"тип":"реверсивная виброплита предыдущего поколения (300-500 кг), бензин","артикул":"5100009657 (bakautprof; kuvalda подтверждает тот же артикул)","вес":"340 кг (каталог, вес в упаковке по ryvok); с пластинами 324 кг / без пластин 301 кг (wackerneuson.com.ru); 332 кг (kuvalda)","центробежная сила":"55 кН (номенклатура 5545; kuvalda, ryvok) — есть источник с 45 кН (см. конфликт)","двигатель":"Honda GX390, 389 см³, 4-тактный бензиновый","мощность":"8.6-11.7 л.с. (8610 Вт по kuvalda; 9.6 л.с. по ryvok)","плита":"базовая 900 x 450 мм, с навесными пластинами рабочая ширина до 600 мм (vekprom); ryvok указывает 900x600","частота":"69 Гц","скорость":"27 м/мин","производительность":"972 м²/ч","расход топлива":"2 л/ч (ryvok) / 3.5 л/ч (kuvalda)","топливный бак":"6.1 л","масло в картере":"0.75 л","реверс":"гидравлический","глубина уплотнения":"до 550 мм (данные дилеров)","Применение":"Специалист по тяжёлым почвам на бензине: глубокие слои, брусчатка среднего и большого веса, дорожные работы; альтернатива дизельным плитам 400-500 кг.","Особенности":"Возбудитель с двумя сбалансированными эксцентриками; Инновационная направляющая рукоятка с очень низкой вибрацией; Сменные расширительные пластины 450 -> 600 мм; Предыдущее поколение: в актуальной линейке NextGen заменена связкой BPU5260Ah/DPU5260*","Разновидности":"BPU5545A арт. 5100009657 (в продаже у bakautprof); DPU5545He/Heap/Hehap — дизельные собратья той же платформы","Запчасти и расходники":"Каталог запчастей Wacker Neuson серии SP (shop.wackerneuson.com) по модели BPU5545A (Открытая SP-PDF ссылка не зафиксирована)"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_benzinovaya_wacker_neuson_bpu_5545a_340_kg/';
UPDATE products SET specs=specs||'{"тип":"реверсивная виброплита предыдущего поколения, бензин","артикул":"5000610345 (bakautprof)","вес":"308 кг (bakautprof, td-set); 322 кг с пластинами (diamondtool: диапазон BPU/DPU4045 322-368 кг)","центробежная сила":"40 кН","двигатель":"Honda GX270, 1-цилиндровый 4-тактный бензиновый (wacker.neuson.ru)","мощность":"6.6 кВт / 8.9-9 л.с. (bakautprof, td-set)","плита":"базовая 450 x 900 мм (bakautprof); 500 x 900 мм (td-set); расширительные пластины опционально","скорость":"24 м/мин","расход топлива":"1.6 л/ч","реверс":"гидравлический, привод через центробежную автоматическую муфту и ременную передачу","материал плиты":"высокопрочный чугун GJS-700","Применение":"Бензиновая альтернатива DPU4045 в среднем классе: траншеи, засыпки, работы там, где нежелателен дизель; брусчатка, ремонт дорог.","Особенности":"Возбудитель с двумя сбалансированными эксцентриками (+10-12% к эффективности уплотнения); Центробежная муфта — запуск без нагрузки; Встроенные транспортировочные колёса, устойчивые к горячему асфальту; Основание GJS-700, складная рукоять с демпферами и боковым управлением; Предыдущее поколение; в актуальной линейке заменена платформой NextGen","Разновидности":"Комплектация с расширительными пластинами плиты основания (опция); Дизельные собратья: DPU4045He / DPU4045Ye(h)","Запчасти и расходники":"Каталог запчастей Wacker Neuson серии SP (shop.wackerneuson.com) по модели BPU4045A (Открытая SP-PDF ссылка не зафиксирована)"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_reversivnaya_benzinovaya_wacker_neuson_bpu_4045_a_308kg/';
UPDATE products SET specs=specs||'{"тип":"компактная прямоходная виброплита M-серии, бензин","артикул":"5100067424 (MP12 CN, bakautprof); MP12-CE = 5100055366; MP12 = 0630380 (atlas-stt)","вес":"64 кг (atlas-stt, virent) / 65 кг (каталог bakautprof)","центробежная сила":"12 кН","двигатель":"Loncin G210F, 212 см³, 4-тактный, одноцилиндровый, воздушное охлаждение, ручной стартер","мощность":"4.4 кВт при рабочих оборотах","плита ШxД":"350 x 521 мм, чугун","скорость":"до 25 м/мин","производительность":"до 550 м²/ч","расход топлива":"~1 л/ч","топливный бак":"3.6 л (virent: 3 л)","уклон":"до 30 %","глубина уплотнения":"~120 мм (данные прокатчика)","Применение":"Самая компактная плита серии: узкие траншеи, ямы, бордюры, точечный ремонт и благоустройство; малый вес — переносимость одним человеком вдвоём.","Особенности":"Основание 350 мм — работа в особенно узких траншеях; Жесткая опорная плита из ковкого чугуна; Запатентованная рукоятка с амортизатором; Подшипники вибратора пригодны для горячего асфальта; Циклонная 3-ступенчатая фильтрация воздуха; Опции: водяной бак с системой подачи воды, транспортировочные колёса","Разновидности":"MP 12 CN арт. 5100067424 (новая позиция bakautprof); MP 12-CE арт. 5100055366; MP 12 арт. 0630380","Запчасти и расходники":"Ремень клиновой V-belt (серии MP; VP), арт. 5000117023 (https://bakautprof.ru/catalog/vibroplity/vibroplita_pryamokhodnaya_benzinovaya_wacker_neuson_mp15_ce_83_kg_0630338 (сопутствующие товары серии MP))","Инструкции PDF":"https://virent.ru/doc/documents/173749.doc; https://atlas-stt.ru/upload/iblock/633/oz38yv4ebc1nmuobuxnzyg5nu4t33ol1/Vibroplita_wacker_neuson_MP_RUS.pdf"}'::jsonb, updated_at=now() WHERE source_url='https://bakautprof.ru/catalog/vibroplity/vibroplita_pryamokhodnaya_wacker_neuson_mp_12_cn_65kg/';
